const QDRANT_URL = 'http://qdrant:6333';
const QDRANT_API_KEY = process.env.QDRANT_API_KEY || '';
const OLLAMA_URL = 'http://host.docker.internal:11434';

async function qdrantScroll(collection, filter, limit=100) {
  const body = {limit, with_payload: true, with_vector: false};
  if (filter) body.filter = filter;
  const r = await fetch(`${QDRANT_URL}/collections/${collection}/points/scroll`, {
    method: 'POST', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify(body)
  });
  const d = await r.json();
  return d.result?.points || [];
}

async function qdrantStore(collection, id, vector, payload) {
  await fetch(`${QDRANT_URL}/collections/${collection}/points`, {
    method: 'PUT', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify({points: [{id, vector, payload}]})
  });
}

async function embed(text) {
  const r = await fetch(`${OLLAMA_URL}/api/embed`, {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({model: 'nomic-embed-text', input: text})
  });
  const d = await r.json();
  return d.embeddings?.[0] || null;
}

function uuid() { return crypto.randomUUID(); }

const trajectories = await qdrantScroll('trajectories', null, 200);
const now = Date.now();
const recent = trajectories.filter(t => {
  const created = new Date(t.payload?.created_at || 0).getTime();
  return (now - created) < 30 * 24 * 60 * 60 * 1000;
});

const sequences = {};
for (const t of recent) {
  const tools = t.payload?.tool_sequence || t.payload?.steps || [];
  if (!Array.isArray(tools) || tools.length < 3) continue;
  const key = tools.slice(0, 5).join(' -> ');
  if (!sequences[key]) sequences[key] = {count: 0, tools, examples: []};
  sequences[key].count++;
  sequences[key].examples.push(t.id);
}

const patterns = Object.entries(sequences).filter(([,v]) => v.count >= 3);
let proposed = 0;

for (const [key, pattern] of patterns) {
  const vec = await embed('skill pattern: ' + key);
  if (vec) {
    await qdrantStore('discovered_skills', uuid(), vec, {
      pattern: key, tool_sequence: pattern.tools, occurrence_count: pattern.count,
      example_trajectories: pattern.examples.slice(0, 5),
      proposed_at: new Date().toISOString(), status: 'proposed',
      source: 'auto-discovered'
    });
    proposed++;
  }
}

return [{
  json: {
    trace_id: uuid(),
    summary: {
      trajectories_analyzed: recent.length,
      patterns_found: patterns.length,
      skills_proposed: proposed
    }
  }
}];

// kernel-audit-emitter (POC integration)
const crypto = require('crypto');

const upstream = $input.first().json || {};
const trace_id = upstream.trace_id;
const summary = upstream.summary || {};

if (!trace_id) {
  throw new Error('KER-AE-002 missing required payload field: trace_id (upstream node must supply it)');
}

const stream_id = $workflow.id;
const node_id = ($node && $node.id) || ($node && $node.name) || 'unknown';
const parent_id = `${stream_id}:${node_id}`;

if (!parent_id.match(/^[A-Za-z0-9_-]+:[A-Za-z0-9_-]+$/)) {
  throw new Error(`KER-AE-002 parent_id failed F-12 pattern: ${parent_id}`);
}

const auditRow = {
  event_type: 'memory.skill_discovery.cron_completed',
  trace_id,
  parent_id,
  timestamp: new Date().toISOString(),
  response: JSON.stringify(summary),
  tool_calls: [
    { tool_name: 'qdrant_scroll', input_summary: 'trajectories last 30d' },
    { tool_name: 'ollama_embed', input_summary: `${summary.patterns_found || 0} patterns` },
    { tool_name: 'qdrant_store', input_summary: `${summary.skills_proposed || 0} skills proposed` }
  ]
};

const token = $env.KERNEL_AUDIT_TOKEN || (typeof process !== 'undefined' && process.env && process.env.KERNEL_AUDIT_TOKEN);
if (!token) {
  throw new Error('KER-AE-003 audit_hmac_token_missing — set KERNEL_AUDIT_TOKEN env var on the n8n instance');
}

const canonical = JSON.stringify(auditRow, Object.keys(auditRow).sort());
const hmacSignature = crypto.createHmac('sha256', token).update(canonical, 'utf8').digest('hex');

const endpoint = $env.KERNEL_AUDIT_ENDPOINT || 'http://localhost:5681/audit/emit';

return [{
  json: {
    auditRow,
    hmacSignature,
    endpoint,
    _meta: {
      n8n_execution_id: $execution.id,
      n8n_node_id: node_id,
      n8n_workflow_id: stream_id,
      canonical_bytes: canonical.length
    }
  }
}];
